"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[1100],{67248:e=>{e.exports=JSON.parse('{"functions":[{"name":"Event","desc":"Creates an event and returns its `connect` and `fire` halves. Listeners\\nrun on their own threads via `task.spawn`, so a yielding or erroring\\nlistener never blocks the firer or the other listeners.","params":[],"returns":[{"desc":"Registers a listener; returns its disconnect.","lua_type":"Connect<Args...>"},{"desc":"Fires the event to every current listener.","lua_type":"(Args...) -> ()"}],"function_type":"static","source":{"line":39,"path":"plugin/event/init.luau"}}],"properties":[],"types":[{"name":"Connect","desc":"Registers a listener and returns a function that disconnects it.","lua_type":"(callback: (Args...) -> ()) -> () -> ()","source":{"line":26,"path":"plugin/event/init.luau"}}],"name":"Event","desc":"A minimal signal, split into its two capabilities so producers and\\nconsumers can be handed different halves:\\n\\n```lua\\nlocal onThing, fireThing = Event()\\nlocal disconnect = onThing(function(value)\\n\\tprint(\\"got\\", value)\\nend)\\nfireThing(123)\\ndisconnect()\\n```","source":{"line":19,"path":"plugin/event/init.luau"}}')}}]);